function TimerRing({tl,total,step,paused,compact}){const m=Math.floor(tl/60),s=tl%60;const strokeColor=step<=3?ds.teal:ds.gold;const sz=compact?130:196;const r=compact?54:82;const sw=compact?6:8;const ci=2*Math.PI*r,progress=tl/total,offset=ci*(1-progress),cx=sz/2,cy=sz/2;return <div style={{position:"relative",width:sz,height:sz,margin:"0 auto",flexShrink:0}}><svg width={sz} height={sz} style={{transform:"rotate(-90deg)"}}><circle cx={cx} cy={cy} r={r} fill="none" stroke={`${strokeColor}20`} strokeWidth={sw}/><circle cx={cx} cy={cy} r={r} fill="none" stroke={strokeColor} strokeWidth={sw} strokeDasharray={ci} strokeDashoffset={offset} strokeLinecap="round" style={{transition:"stroke-dashoffset 0.3s ease"}}/></svg><div style={{position:"absolute",inset:0,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center"}}><div style={{fontSize:compact?32:48,fontWeight:700,color:ds.warmDk,letterSpacing:"-0.02em",fontVariantNumeric:"tabular-nums"}}>{String(m).padStart(2,"0")}:{String(s).padStart(2,"0")}</div><div style={{fontSize:compact?9:11,fontWeight:600,color:ds.txL,letterSpacing:compact?2:3,textTransform:"uppercase",marginTop:compact?0:2}}>{paused?"PAUSED":"SECONDS"}</div></div></div>}
