function TimerScr({config,onComplete,onCancel,pearls,onSavePearl}){const[step,setStep]=useState(1);const[tl,setTl]=useState(60);const[paused,setPaused]=useState(false);const[elapsed,setElapsed]=useState(0);const[s1Txt,setS1Txt]=useState("");const[s1Stars,setS1Stars]=useState(new Array(4).fill(0));const[s2Stars,setS2Stars]=useState([]);const[s2Mode,setS2Mode]=useState("quick");const[s3,setS3]=useState(["","","","",""]);const[s4,setS4]=useState(["","",""]);const[s4Tags,setS4Tags]=useState([]);const[s5,setS5]=useState(["","",""]);const[actPlan,setActPlan]=useState("");const[pearlSaved,setPearlSaved]=useState(false);const[pearlUsed,setPearlUsed]=useState(false);const scrollRef=useRef(null);const[compact,setCompact]=useState(false);useEffect(()=>{const ck=()=>setCompact(window.innerWidth<600);ck();window.addEventListener("resize",ck);return()=>window.removeEventListener("resize",ck)},[]);const ref=useRef(null);useEffect(()=>{if(paused)return;ref.current=setInterval(()=>{setTl(p=>{if(p<=1){if(step<5){setStep(s=>s+1);return 60}else{clearInterval(ref.current);onComplete(elapsed+60);return 0}}return p-1});setElapsed(e=>e+1)},1000);return()=>clearInterval(ref.current)},[paused,step]);useEffect(()=>{if(scrollRef.current)scrollRef.current.scrollTop=0},[step]);useEffect(()=>{if(step===2){const len=s2Mode==="quick"?STEPS[1].quickPrompts.length:STEPS[1].deepPrompts.length;setS2Stars(new Array(len).fill(0))}},[step,s2Mode]);const st=STEPS[step-1];const StepIcon=st.icon;const stepColor=step<=3?ds.teal:ds.gold;const matchedPearl=step===3&&s1Txt.trim().length>0?pearls.find(p=>p.dx.toLowerCase().includes(s1Txt.trim().toLowerCase())):null;const goNext=()=>{if(step<5){setStep(x=>x+1);setTl(60)}else onComplete(elapsed)};const goBack=()=>{if(step>1){setStep(x=>x-1);setTl(60)}};const toggleS1Star=i=>{const n=[...s1Stars];n[i]=n[i]?0:1;setS1Stars(n)};const toggleS2Star=i=>{const n=[...s2Stars];n[i]=n[i]?0:1;setS2Stars(n)};const calcAuto=arr=>{if(!arr.length)return 0;return arr.filter(Boolean).length/arr.length};const s2Prompts=s2Mode==="quick"?STEPS[1].quickPrompts||[]:STEPS[1].deepPrompts||[];
return <div style={{flex:1,display:"flex",flexDirection:"column",paddingTop:compact?16:54,background:ds.surface,minHeight:0}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:compact?"4px 16px 0":"8px 20px 0",flexShrink:0}}><button onClick={onCancel} style={{background:"none",border:"none",cursor:"pointer"}}><ChevronLeft size={compact?20:22} color={ds.txB}/></button><div style={{display:"flex",alignItems:"center",gap:6}}><span style={{fontSize:compact?13:15,fontWeight:700,color:ds.warmDk,letterSpacing:"-0.02em"}}>Step {step}</span><span style={{color:ds.txL,fontSize:compact?11:13}}>•</span>{[1,2,3,4,5].filter(n=>n!==step).map(n=><span key={n} style={{fontSize:compact?11:13,fontWeight:n<step?600:400,color:n<step?ds.pri:ds.txL}}>{n}</span>)}</div><button style={{background:"none",border:"none",cursor:"pointer"}}><ClipboardList size={compact?16:18} color={ds.txB}/></button></div><div style={{display:"flex",gap:4,padding:compact?"6px 16px 0":"8px 20px 0",flexShrink:0}}>{STEPS.map((_,i)=><div key={i} style={{flex:1,height:3,borderRadius:2,background:i<step?stepColor:ds.bd,opacity:i<step?1:0.4,transition:"all 0.3s ease"}}/>)}</div><div style={{padding:compact?"8px 0 0":"12px 0 0",flexShrink:0}}><div onClick={()=>setPaused(!paused)} style={{cursor:"pointer"}}><TimerRing tl={tl} total={60} step={step} paused={paused} compact={compact}/></div></div><div style={{textAlign:"center",padding:compact?"4px 16px 0":"10px 20px 0",flexShrink:0}}><div style={{display:"inline-flex",alignItems:"center",gap:6,background:`${stepColor}15`,padding:compact?"4px 12px":"6px 16px",borderRadius:20}}><StepIcon size={compact?14:16} color={stepColor}/><span style={{fontSize:compact?12:14,fontWeight:700,color:stepColor,letterSpacing:"-0.02em"}}>{st.name}</span></div>{!compact&&<p style={{fontSize:13,color:ds.txB,margin:"4px 0 0",lineHeight:1.5}}>{st.instruction}</p>}</div><div ref={scrollRef} style={{flex:1,overflowY:"auto",minHeight:0,padding:"12px 16px 0",WebkitOverflowScrolling:"touch"}}>{step===1&&<><div style={{...ds.card,padding:14}}><p style={{fontSize:13,color:ds.txB,margin:"0 0 8px"}}>Ask the learner:</p>{st.prompts.map((p,i)=><div key={i} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"8px 0",borderBottom:i<st.prompts.length-1?`1px solid ${ds.bdL}`:"none"}}><span style={{fontSize:13,color:ds.tx,lineHeight:1.5,flex:1}}>• {p}</span><button onClick={()=>toggleS1Star(i)} style={{background:"none",border:"none",cursor:"pointer",padding:4,flexShrink:0}}><Star size={20} color="#D4A76A" fill={s1Stars[i]?"#D4A76A":"none"} strokeWidth={1.5}/></button></div>)}</div><div style={{display:"flex",gap:8,marginTop:10}}><input value={s1Txt} onChange={e=>setS1Txt(e.target.value)} placeholder="Learner's answer (for pearl matching)..." style={{...ds.input,flex:1}}/></div><StarRow label={st.rateLabel} autoCalc={calcAuto(s1Stars)}/></>}{step===2&&<><div style={{display:"flex",justifyContent:"center",gap:0,marginBottom:10}}>{["quick","deep"].map(mode=><button key={mode} onClick={()=>setS2Mode(mode)} style={{padding:"8px 24px",fontSize:13,fontWeight:s2Mode===mode?700:400,color:s2Mode===mode?ds.txW:ds.txB,background:s2Mode===mode?ds.warmDk:"#fff",border:`1px solid ${ds.bd}`,borderRadius:mode==="quick"?"10px 0 0 10px":"0 10px 10px 0",cursor:"pointer",transition:"all 0.2s ease"}}>{mode==="quick"?"Quick":"Deep"}</button>)}</div><div style={{...ds.card,padding:14}}><p style={{fontSize:13,color:ds.txB,margin:"0 0 8px"}}>Explore reasoning:</p>{s2Prompts.map((p,i)=><div key={i} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"8px 0",borderBottom:i<s2Prompts.length-1?`1px solid ${ds.bdL}`:"none"}}><span style={{fontSize:13,color:ds.tx,lineHeight:1.5,flex:1}}>• {p}</span><button onClick={()=>toggleS2Star(i)} style={{background:"none",border:"none",cursor:"pointer",padding:4,flexShrink:0}}><Star size={20} color="#D4A76A" fill={s2Stars[i]?"#D4A76A":"none"} strokeWidth={1.5}/></button></div>)}</div><StarRow label={st.rateLabel} autoCalc={calcAuto(s2Stars)}/></>}{step===3&&<>{matchedPearl&&!pearlUsed&&<div style={{...ds.card,padding:12,marginBottom:10,borderLeft:`3px solid ${ds.gold}`}}><div style={{display:"flex",alignItems:"center",gap:6}}><Star size={14} color={ds.gold}/><span style={{fontSize:13,fontWeight:700,color:ds.gold}}>Saved pearl for "{matchedPearl.dx}"</span></div><p style={{fontSize:11,color:ds.txB,margin:"4px 0 0"}}>Tap below to auto-fill your templates</p><button onClick={()=>{setS3([...matchedPearl.pts]);setPearlUsed(true)}} style={{width:"100%",marginTop:8,padding:"10px",...ds.btnSec,fontSize:13,fontWeight:600,color:ds.gold,borderColor:ds.gold}}>Use Saved Pearl →</button></div>}<div style={{...ds.card,padding:14}}><p style={{fontSize:13,color:ds.txB,margin:"0 0 10px"}}>Teach 1-2 key points:</p><div style={{marginBottom:10}}><span style={{fontSize:13,color:ds.txB}}>• One important thing to remember is...</span><input value={s3[0]} onChange={e=>{const n=[...s3];n[0]=e.target.value;setS3(n)}} placeholder="___" style={{...ds.input,marginTop:4,background:s3[0]?`${ds.gold}08`:ds.bdL,borderColor:s3[0]?ds.gold:ds.bd}}/></div><div style={{marginBottom:10}}><div style={{display:"flex",alignItems:"center",gap:4,flexWrap:"wrap"}}><span style={{fontSize:13,color:ds.txB}}>• In patients with</span><input value={s3[1]} onChange={e=>{const n=[...s3];n[1]=e.target.value;setS3(n)}} placeholder="condition" style={{...ds.input,width:100,padding:"8px 10px",background:s3[1]?`${ds.gold}08`:ds.bdL,borderColor:s3[1]?ds.gold:ds.bd}}/><span style={{fontSize:13,color:ds.txB}}>always check</span><input value={s3[2]} onChange={e=>{const n=[...s3];n[2]=e.target.value;setS3(n)}} placeholder="what" style={{...ds.input,width:100,padding:"8px 10px",background:s3[2]?`${ds.gold}08`:ds.bdL,borderColor:s3[2]?ds.gold:ds.bd}}/></div></div><div style={{marginBottom:10}}><span style={{fontSize:13,color:ds.txB}}>• First-line treatment is usually...</span><input value={s3[3]} onChange={e=>{const n=[...s3];n[3]=e.target.value;setS3(n)}} placeholder="___" style={{...ds.input,marginTop:4,background:s3[3]?`${ds.gold}08`:ds.bdL,borderColor:s3[3]?ds.gold:ds.bd}}/></div><div><span style={{fontSize:13,color:ds.txB}}>• Red flag:</span><input value={s3[4]} onChange={e=>{const n=[...s3];n[4]=e.target.value;setS3(n)}} placeholder="___" style={{...ds.input,marginTop:4,background:s3[4]?`${ds.gold}08`:ds.bdL,borderColor:s3[4]?ds.gold:ds.bd}}/></div></div><div style={{display:"flex",gap:8,marginTop:10}}><button onClick={()=>{onSavePearl({dept:config.preDept,dx:s1Txt||"General",pts:[...s3]});setPearlSaved(true)}} disabled={pearlSaved} style={{flex:1,padding:"12px",...ds.btnSec,fontSize:13,fontWeight:600,color:pearlSaved?ds.green:ds.txB,borderColor:pearlSaved?ds.green:ds.bd,background:pearlSaved?`${ds.green}10`:"#fff",display:"flex",alignItems:"center",justifyContent:"center",gap:6}}>{pearlSaved?<><Check size={14}/><span>Pearl Saved</span></>:<><Star size={14}/><span>Save as teaching pearl</span></>}</button></div></>}{step===4&&<><div style={{...ds.card,padding:14}}><p style={{fontSize:13,color:ds.txB,margin:"0 0 10px"}}>Provide positive feedback:</p>{st.starters.map((s,i)=><div key={i} style={{display:"flex",alignItems:"center",marginBottom:8,borderRadius:12,border:`1px solid ${ds.bd}`,overflow:"hidden"}}><span style={{padding:"12px",fontSize:13,color:ds.txB,fontWeight:500,whiteSpace:"nowrap",borderRight:`1px solid ${ds.bd}`,background:"#fff",flexShrink:0}}>{s}</span><input value={s4[i]} onChange={e=>{const n=[...s4];n[i]=e.target.value;setS4(n)}} placeholder="___" style={{flex:1,padding:"12px",border:"none",fontSize:13,outline:"none",background:ds.bdL,fontFamily:"inherit"}}/></div>)}</div><div style={{display:"flex",flexWrap:"wrap",gap:6,marginTop:10}}>{st.tags.map(tg=><button key={tg} onClick={()=>setS4Tags(p=>p.includes(tg)?p.filter(x=>x!==tg):[...p,tg])} style={{padding:"7px 14px",borderRadius:14,border:s4Tags.includes(tg)?"none":`1px solid ${ds.bd}`,background:s4Tags.includes(tg)?ds.green:"#fff",color:s4Tags.includes(tg)?ds.txW:ds.txB,fontSize:12,fontWeight:s4Tags.includes(tg)?600:400,cursor:"pointer",display:"flex",alignItems:"center",gap:4,boxShadow:!s4Tags.includes(tg)?`inset 0 0 0 1px ${ds.bd}`:"none"}}>{s4Tags.includes(tg)&&<Check size={12}/>}<span>{tg}</span></button>)}</div></>}{step===5&&<><div style={{...ds.card,padding:14}}><p style={{fontSize:13,color:ds.txB,margin:"0 0 10px"}}>Guide improvement:</p>{st.starters.map((s,i)=><div key={i} style={{display:"flex",alignItems:"center",marginBottom:8,borderRadius:12,border:`1px solid ${ds.bd}`,overflow:"hidden"}}><span style={{padding:"12px",fontSize:13,color:ds.txB,fontWeight:500,whiteSpace:"nowrap",borderRight:`1px solid ${ds.bd}`,background:"#fff",flexShrink:0}}>{s}</span><input value={s5[i]} onChange={e=>{const n=[...s5];n[i]=e.target.value;setS5(n)}} placeholder="___" style={{flex:1,padding:"12px",border:"none",fontSize:13,outline:"none",background:ds.bdL,fontFamily:"inherit"}}/></div>)}</div><div style={{...ds.card,padding:14,marginTop:10}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:6}}><span style={{fontSize:15,fontWeight:700,color:ds.tx,letterSpacing:"-0.02em"}}>Action Plan</span><Edit size={16} color={ds.txL}/></div><textarea value={actPlan} onChange={e=>setActPlan(e.target.value)} placeholder="What should the learner study next?" rows={2} style={{...ds.input,resize:"none",background:ds.bdL}}/></div></>}<div style={{height:8}}/></div><div style={{display:"flex",gap:12,padding:"12px 16px 36px",flexShrink:0}}>{step===1?<button onClick={goNext} style={{...ds.btnSec,flex:1,padding:"14px",fontSize:14,fontWeight:600,color:ds.txB}}>Skip</button>:<button onClick={goBack} style={{...ds.btnSec,flex:1,padding:"14px",fontSize:15,fontWeight:600,color:ds.tx,display:"flex",alignItems:"center",justifyContent:"center"}}><ChevronLeft size={18}/></button>}<button onClick={goNext} style={{...ds.btnPri,flex:3,padding:"14px",fontSize:15,background:step===5?`linear-gradient(135deg,${ds.green},#16A34A)`:ds.gradBtn,boxShadow:step===5?"0 4px 14px rgba(34,197,94,0.3)":"0 4px 14px rgba(139,107,174,0.3)"}}>{step===5?<span style={{display:"flex",alignItems:"center",justifyContent:"center",gap:6}}><Check size={16}/>Finish</span>:"Next →"}</button></div></div>}
function LogScr({config,dur,onSave}){const[u,setU]=useState(null);const[ld,setLd]=useState(null);return <div style={{flex:1,display:"flex",flexDirection:"column",paddingTop:54,background:ds.surface,minHeight:0}}><div style={{padding:"12px 20px 0",flexShrink:0}}><h2 style={{fontSize:24,fontWeight:700,color:ds.warmDk,margin:0,letterSpacing:"-0.02em"}}>Quick Log</h2><p style={{fontSize:13,color:ds.txB,margin:"4px 0 0"}}>Session: {Math.floor(dur/60)}m {dur%60}s</p></div><div style={{flex:1,padding:16,overflowY:"auto",minHeight:0}}><div style={{display:"flex",gap:8,marginBottom:16}}>{[["LEARNER",config?.student?.name||config?.learner],["CASE",config?.caseType],["DEPT",config?.preDept]].map(([l,v])=><div key={l} style={{flex:1,...ds.card,padding:"10px 12px"}}><div style={{fontSize:10,color:ds.txL,fontWeight:600,letterSpacing:1}}>{l}</div><div style={{fontSize:13,fontWeight:600,color:ds.tx,marginTop:2}}>{v}</div></div>)}</div><div style={{marginBottom:16}}><label style={{fontSize:13,fontWeight:600,color:ds.txB,display:"block",marginBottom:6}}>Diagnosis</label><input placeholder="e.g., Pneumonia" style={ds.input}/></div><div style={{marginBottom:16}}><label style={{fontSize:13,fontWeight:600,color:ds.txB,display:"block",marginBottom:8}}>Learner gave diagnosis?</label><div style={{display:"flex",gap:10}}>{[true,false].map(v=><button key={String(v)} onClick={()=>setLd(v)} style={{flex:1,padding:"12px",borderRadius:12,border:ld===v?"none":`1px solid ${ds.bd}`,background:ld===v?(v?`${ds.green}15`:`${ds.red}15`):"#fff",color:ld===v?(v?ds.green:ds.red):ds.tx,fontSize:14,fontWeight:600,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",gap:6}}>{v?<><Check size={14}/><span>Yes</span></>:<><X size={14}/><span>No</span></>}</button>)}</div></div><div style={{marginBottom:16}}><label style={{fontSize:13,fontWeight:600,color:ds.txB,display:"block",marginBottom:8}}>Teaching usefulness</label><div style={{display:"flex",gap:6}}>{[1,2,3,4,5,6].map(n=><button key={n} onClick={()=>setU(n)} style={{flex:1,padding:"12px 0",borderRadius:10,border:u===n?"none":`1px solid ${ds.bd}`,background:u===n?ds.pri:"#fff",color:u===n?ds.txW:ds.tx,fontSize:16,fontWeight:700,cursor:"pointer"}}>{n}</button>)}</div></div></div><div style={{display:"flex",gap:12,padding:"12px 16px 36px",flexShrink:0}}><button onClick={onSave} style={{...ds.btnSec,flex:1,padding:"14px",fontSize:14,fontWeight:600,color:ds.txB}}>Skip</button><button onClick={onSave} style={{...ds.btnPri,flex:2,padding:"14px",fontSize:15,background:ds.gradBtn,display:"flex",alignItems:"center",justifyContent:"center",gap:6}}><Check size={16}/><span>Save</span></button></div></div>}
function HistoryScr(){const[exp,setExp]=useState(null);const stepColors=[ds.teal,ds.teal,ds.lavender,ds.green,ds.gold];const grouped={};ENCOUNTERS.forEach(e=>{if(!grouped[e.date])grouped[e.date]=[];grouped[e.date].push(e)});return <div style={{flex:1,display:"flex",flexDirection:"column",paddingTop:54,background:ds.surface,minHeight:0}}><div style={{padding:"12px 20px 12px",flexShrink:0}}><h2 style={{fontSize:24,fontWeight:700,color:ds.warmDk,margin:"0 0 4px",letterSpacing:"-0.02em"}}>Encounter History</h2></div><div style={{flex:1,overflowY:"auto",minHeight:0,padding:"0 16px 20px",WebkitOverflowScrolling:"touch"}}>{Object.entries(grouped).map(([date,encs])=><div key={date}><p style={{fontSize:11,fontWeight:700,color:ds.txL,letterSpacing:1,margin:"14px 0 6px"}}>{date}</p>{encs.map(e=>{const stu=STUDENTS.find(s=>s.id===e.studentId);return <div key={e.id} onClick={()=>setExp(exp===e.id?null:e.id)} style={{...ds.card,padding:14,marginBottom:8,cursor:"pointer",border:exp===e.id?`2px solid ${ds.pri}`:"2px solid transparent"}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start"}}><div style={{flex:1}}><span style={{fontSize:15,fontWeight:700,color:ds.tx}}>{e.dx}</span>{stu&&<span style={{fontSize:11,color:ds.pri,marginLeft:8,fontWeight:600}}>{stu.name}</span>}<div style={{fontSize:13,color:ds.txB,marginTop:3}}>{e.dept} · {e.lr} · {e.ct}</div></div><div style={{textAlign:"right"}}><div style={{fontSize:11,color:ds.txL}}>{e.time}</div>{e.s1Stars&&<div style={{display:"flex",gap:1,marginTop:2}}>{[1,2,3,4,5].map(i=><Star key={i} size={10} color={ds.gold} fill={i<=Math.round(calcStars(e))?ds.gold:"none"}/>)}</div>}</div></div><div style={{display:"flex",gap:3,marginTop:8}}>{e.steps.map((s,i)=><div key={i} style={{display:"flex",alignItems:"center",gap:3,flex:1}}><div style={{width:8,height:8,borderRadius:"50%",background:s?stepColors[i]:ds.bd,flexShrink:0}}/><div style={{height:2,flex:1,borderRadius:1,background:s?`${stepColors[i]}30`:ds.bdL}}/></div>)}</div>{exp===e.id&&<div style={{marginTop:10,paddingTop:10,borderTop:`1px solid ${ds.bd}`}}><div style={{display:"flex",gap:6,marginBottom:10}}>{[["Useful",`${e.useful}/6`,ds.pri],["Steps",`${e.steps.filter(Boolean).length}/5`,ds.warmDk]].map(([l,v,c])=><div key={l} style={{flex:1,background:ds.bdL,borderRadius:10,padding:8,textAlign:"center"}}><div style={{fontSize:18,fontWeight:700,color:c}}>{v}</div><div style={{fontSize:10,color:ds.txL,marginTop:2}}>{l}</div></div>)}</div>{e.s3.some(x=>x)&&<div style={{background:ds.bdL,borderRadius:10,padding:10,marginBottom:6}}><p style={{fontSize:10,fontWeight:700,color:ds.lavender,margin:"0 0 6px"}}>TAUGHT</p>{e.s3.filter(x=>x).map((pt,i)=><div key={i} style={{fontSize:12,color:ds.tx,marginBottom:3}}>• {pt}</div>)}</div>}{e.tags.length>0&&<div style={{display:"flex",gap:4,flexWrap:"wrap"}}>{e.tags.map(tg=><span key={tg} style={{fontSize:9,background:`${ds.green}15`,color:ds.green,padding:"2px 8px",borderRadius:10,fontWeight:600}}>● {tg}</span>)}</div>}</div>}</div>})}</div>)}</div></div>}
function StatsScr(){const stepComp=[100,96,85,77,62];const mx=Math.max(...WDATA.map(d=>d.s),1);const stepColors=[ds.teal,ds.teal,ds.lavender,ds.green,ds.gold];return <div style={{flex:1,display:"flex",flexDirection:"column",paddingTop:54,background:ds.surface,minHeight:0}}><div style={{padding:"12px 20px 12px",flexShrink:0}}><h2 style={{fontSize:24,fontWeight:700,color:ds.warmDk,margin:0,letterSpacing:"-0.02em"}}>Teaching Analytics</h2></div><div style={{flex:1,overflowY:"auto",minHeight:0,padding:"0 16px 20px",WebkitOverflowScrolling:"touch"}}><div style={{background:ds.gradHdr,borderRadius:16,padding:16,marginBottom:14,color:ds.txW}}><div style={{display:"flex",alignItems:"center",gap:6,marginBottom:6}}><Lightbulb size={14} color="#FCD34D"/><span style={{fontSize:11,fontWeight:700,letterSpacing:1,opacity:0.8}}>INSIGHT</span></div><p style={{fontSize:13,margin:0,lineHeight:1.5}}>You skip <strong>Step 5</strong> in 38% of sessions.</p></div><div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:14}}>{[{n:"26",l:"Sessions",s:"+4 this week",c:ds.pri,Icon:TimerIcon},{n:"4m 52s",l:"Avg Duration",s:"Target: 5m",c:ds.warmDk,Icon:Clock},{n:"8",l:"Pearls",s:"3 reused",c:ds.lavender,Icon:Star},{n:"72%",l:"5-Step Rate",s:"↑12%",c:ds.green,Icon:Check}].map(s=><div key={s.l} style={{...ds.card,padding:14}}><IconCircle Icon={s.Icon} color={s.c} size={32}/><div style={{fontSize:24,fontWeight:700,color:ds.warmDk,marginTop:8}}>{s.n}</div><div style={{fontSize:13,color:ds.txB,marginTop:1}}>{s.l}</div><div style={{fontSize:11,color:s.c,fontWeight:600,marginTop:4}}>{s.s}</div></div>)}</div><div style={{...ds.card,padding:16,marginBottom:14}}><h4 style={{fontSize:15,fontWeight:700,color:ds.warmDk,margin:"0 0 10px"}}>Step Completion</h4>{STEPS.map((s,i)=><div key={i} style={{marginBottom:6}}><div style={{display:"flex",justifyContent:"space-between",marginBottom:2}}><span style={{fontSize:12,color:ds.tx}}>Step {i+1}</span><span style={{fontSize:12,fontWeight:700,color:stepComp[i]>80?ds.green:ds.gold}}>{stepComp[i]}%</span></div><div style={{height:8,borderRadius:4,background:ds.bdL}}><div style={{height:"100%",borderRadius:4,width:`${stepComp[i]}%`,background:stepColors[i]}}/></div></div>)}</div><div style={{...ds.card,padding:16}}><h4 style={{fontSize:15,fontWeight:700,color:ds.warmDk,margin:"0 0 12px"}}>This Week</h4><div style={{display:"flex",alignItems:"flex-end",gap:6,height:80}}>{WDATA.map(d=><div key={d.d} style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",gap:3}}><span style={{fontSize:11,fontWeight:700,color:ds.warmDk}}>{d.s}</span><div style={{width:"100%",borderRadius:6,height:`${Math.max((d.s/mx)*55,3)}px`,background:d.s>0?ds.pri:ds.bdL}}/><span style={{fontSize:10,color:ds.txB}}>{d.d}</span></div>)}</div></div></div></div>}
function StudentHistScr(){const[selStu,setSelStu]=useState(1);const[sdOpen,setSdOpen]=useState(false);const stu=STUDENTS.find(s=>s.id===selStu);const stuEnc=ENCOUNTERS.filter(e=>e.studentId===selStu).sort((a,b)=>a.date.localeCompare(b.date));const starData=stuEnc.map(e=>({date:e.date,dx:e.dx,stars:calcStars(e)}));const avgStars=starData.length?starData.reduce((a,b)=>a+b.stars,0)/starData.length:0;return <div style={{flex:1,display:"flex",flexDirection:"column",paddingTop:54,background:ds.surface,minHeight:0}}><div style={{padding:"12px 20px 12px",flexShrink:0}}><h2 style={{fontSize:24,fontWeight:700,color:ds.warmDk,margin:"0 0 10px",letterSpacing:"-0.02em"}}>Student Progress</h2><div style={{position:"relative"}}><button onClick={()=>setSdOpen(!sdOpen)} style={{...ds.input,display:"flex",justifyContent:"space-between",alignItems:"center",cursor:"pointer",fontWeight:500,color:ds.tx}}>{stu?.name||"Select..."}<ChevronDown size={16} color={ds.txL}/></button>{sdOpen&&<div style={{position:"absolute",left:0,right:0,top:"100%",zIndex:50,background:"#fff",borderRadius:16,boxShadow:"0 8px 30px rgba(0,0,0,0.15)",marginTop:4,maxHeight:200,overflowY:"auto",border:`1px solid ${ds.bd}`}}>{STUDENTS.map(s=><div key={s.id} onClick={()=>{setSelStu(s.id);setSdOpen(false)}} style={{padding:"12px 16px",cursor:"pointer",fontSize:13,color:s.id===selStu?ds.pri:ds.tx,fontWeight:s.id===selStu?600:400,borderBottom:`1px solid ${ds.bdL}`}}>{s.name}<span style={{fontSize:11,color:ds.txL,marginLeft:8}}>{s.level}</span></div>)}</div>}</div></div><div style={{flex:1,overflowY:"auto",minHeight:0,padding:"0 16px 20px",WebkitOverflowScrolling:"touch"}}>{stu&&<div style={{...ds.card,padding:16,marginBottom:12}}><div style={{display:"flex",alignItems:"center",gap:12}}><IconCircle Icon={User} color={ds.coral} size={44}/><div><div style={{fontSize:16,fontWeight:700,color:ds.tx}}>{stu.name}</div><div style={{fontSize:13,color:ds.txB}}>{stu.level} · {stu.dept}{stu.year?` · ${stu.year}`:""}</div></div></div><div style={{display:"flex",gap:8,marginTop:12}}><div style={{flex:1,background:ds.bdL,borderRadius:10,padding:10,textAlign:"center"}}><div style={{fontSize:20,fontWeight:700,color:ds.warmDk}}>{stuEnc.length}</div><div style={{fontSize:10,color:ds.txL}}>Sessions</div></div><div style={{flex:1,background:ds.bdL,borderRadius:10,padding:10,textAlign:"center"}}><div style={{display:"flex",justifyContent:"center",gap:1}}>{[1,2,3,4,5].map(i=><Star key={i} size={14} color={ds.gold} fill={i<=Math.round(avgStars)?ds.gold:"none"}/>)}</div><div style={{fontSize:10,color:ds.txL,marginTop:2}}>Avg Rating</div></div><div style={{flex:1,background:ds.bdL,borderRadius:10,padding:10,textAlign:"center"}}><div style={{fontSize:20,fontWeight:700,color:starData.length>=2&&starData[starData.length-1].stars>starData[0].stars?ds.green:ds.gold}}>{starData.length>=2?(starData[starData.length-1].stars>starData[0].stars?"↑":"→"):"-"}</div><div style={{fontSize:10,color:ds.txL}}>Trend</div></div></div></div>}{starData.length>0&&<div style={{...ds.card,padding:16,marginBottom:12}}><h4 style={{fontSize:15,fontWeight:700,color:ds.warmDk,margin:"0 0 12px"}}>Rating Over Time</h4><div style={{display:"flex",alignItems:"flex-end",gap:8,height:100}}>{starData.map((d,i)=><div key={i} style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",gap:4}}><div style={{display:"flex",flexDirection:"column",gap:1}}>{[1,2,3,4,5].map(s=><Star key={s} size={10} color={ds.gold} fill={s<=Math.round(d.stars)?ds.gold:"none"}/>)}</div><div style={{width:"100%",borderRadius:6,height:`${Math.max((d.stars/5)*60,4)}px`,background:`linear-gradient(180deg,${ds.coral},${ds.pri})`}}/><span style={{fontSize:8,color:ds.txL}}>{d.dx.slice(0,6)}</span></div>)}</div></div>}{stuEnc.map(e=><div key={e.id} style={{...ds.card,padding:12,marginBottom:6}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}><div><span style={{fontSize:14,fontWeight:600,color:ds.tx}}>{e.dx}</span><div style={{fontSize:11,color:ds.txL,marginTop:2}}>{e.date} · {e.ct}</div></div><div style={{display:"flex",gap:1}}>{[1,2,3,4,5].map(i=><Star key={i} size={12} color={ds.gold} fill={i<=Math.round(calcStars(e))?ds.gold:"none"}/>)}</div></div></div>)}{stuEnc.length===0&&<p style={{textAlign:"center",color:ds.txL,fontSize:13,marginTop:40}}>No encounters found.</p>}</div></div>}
function MoreScr({onNav,pc}){return <div style={{flex:1,display:"flex",flexDirection:"column",paddingTop:54,background:ds.surface,minHeight:0}}><div style={{padding:"12px 20px 16px",flexShrink:0}}><h2 style={{fontSize:24,fontWeight:700,color:ds.warmDk,margin:0,letterSpacing:"-0.02em"}}>More</h2></div><div style={{flex:1,overflowY:"auto",minHeight:0,padding:"0 16px 20px"}}>{[{l:"Teaching Pearls",d:`${pc} pearls saved`,Icon:Star,c:ds.gold,tg:"pearls"},{l:"About OMP",d:"Learn the model",Icon:BookOpen,c:ds.pri,tg:"about"},{l:"Settings",d:"Timer & data",Icon:Settings,c:ds.txB,tg:"settings"},{l:"Export Data",d:"CSV download",Icon:Download,c:ds.green,tg:null}].map(i=><div key={i.l} onClick={()=>i.tg&&onNav(i.tg)} style={{...ds.card,padding:16,marginBottom:8,display:"flex",alignItems:"center",gap:14,cursor:i.tg?"pointer":"default"}}><IconCircle Icon={i.Icon} color={i.c}/><div style={{flex:1}}><div style={{fontSize:15,fontWeight:700,color:ds.tx}}>{i.l}</div><div style={{fontSize:13,color:ds.txB,marginTop:2}}>{i.d}</div></div><ChevronRight size={16} color={ds.txL}/></div>)}<p style={{textAlign:"center",fontSize:13,color:ds.txB,margin:"24px 0 0",fontWeight:600}}>by Prof. Muneeza Rizwan</p></div></div>}
function AboutScr({onBack}){return <div style={{flex:1,display:"flex",flexDirection:"column",paddingTop:54,background:ds.surface,minHeight:0}}><div style={{padding:"12px 20px",flexShrink:0}}><button onClick={onBack} style={{background:"none",border:"none",cursor:"pointer",fontSize:14,color:ds.pri,fontWeight:600,padding:0,marginBottom:8,display:"flex",alignItems:"center",gap:4}}><ChevronLeft size={16}/>Back</button><h2 style={{fontSize:24,fontWeight:700,color:ds.warmDk,margin:0}}>About OMP</h2></div><div style={{flex:1,overflowY:"auto",minHeight:0,padding:"8px 16px 20px"}}><div style={{background:ds.gradHdr,borderRadius:16,padding:24,textAlign:"center"}}><Logo size={50}/><h3 style={{color:ds.txW,fontSize:18,fontWeight:700,margin:"12px 0 4px"}}>One-Minute Preceptor</h3><p style={{color:"rgba(255,255,255,0.6)",fontSize:13,margin:0,fontWeight:600}}>by Prof. Muneeza Rizwan</p></div></div></div>}
function PearlLib({pearls,onBack}){const[s,setS]=useState("");const f=pearls.filter(p=>!s||p.dx.toLowerCase().includes(s.toLowerCase()));return <div style={{flex:1,display:"flex",flexDirection:"column",paddingTop:54,background:ds.surface,minHeight:0}}><div style={{padding:"12px 20px",flexShrink:0}}><button onClick={onBack} style={{background:"none",border:"none",cursor:"pointer",fontSize:14,color:ds.pri,fontWeight:600,padding:0,marginBottom:8,display:"flex",alignItems:"center",gap:4}}><ChevronLeft size={16}/>Back</button><h2 style={{fontSize:24,fontWeight:700,color:ds.warmDk,margin:"0 0 10px"}}>Teaching Pearls</h2><div style={{position:"relative"}}><Search size={16} color={ds.txL} style={{position:"absolute",left:14,top:"50%",transform:"translateY(-50%)"}}/><input value={s} onChange={e=>setS(e.target.value)} placeholder="Search by diagnosis..." style={{...ds.input,paddingLeft:40}}/></div></div><div style={{flex:1,overflowY:"auto",minHeight:0,padding:"12px 16px 20px"}}>{f.map(p=><div key={p.id} style={{...ds.card,padding:14,marginBottom:8}}><div style={{display:"flex",gap:6,marginBottom:8}}><span style={{fontSize:10,background:`${ds.lavender}25`,color:ds.pri,padding:"3px 8px",borderRadius:6,fontWeight:600}}>{p.dept}</span><span style={{fontSize:10,background:ds.bdL,color:ds.teal,padding:"3px 8px",borderRadius:6,fontWeight:600}}>{p.dx}</span><span style={{marginLeft:"auto"}}><Star size={16} color={ds.gold} fill={p.fav?ds.gold:"none"}/></span></div>{p.pts.filter(x=>x).map((pt,i)=><div key={i} style={{fontSize:13,color:ds.tx,padding:"4px 0",lineHeight:1.5}}><span style={{color:ds.txL,fontSize:11,fontWeight:600}}>{["Remember:","In patients with:","Always check:","Treatment:","Red flag:"][i]}</span> {pt}</div>)}<div style={{display:"flex",justifyContent:"space-between",marginTop:8}}><span style={{fontSize:11,color:ds.txL}}>Used {p.used}x</span><div style={{display:"flex",gap:8}}><button style={{background:"none",border:"none",cursor:"pointer",fontSize:12,color:ds.pri,fontWeight:600,display:"flex",alignItems:"center",gap:2}}><Edit size={12}/>Edit</button><button style={{background:"none",border:"none",cursor:"pointer",fontSize:12,color:ds.red,fontWeight:600,display:"flex",alignItems:"center",gap:2}}><Trash2 size={12}/>Delete</button></div></div></div>)}</div></div>}
function Toast({show}){if(!show)return null;return <div style={{position:"absolute",top:70,left:16,right:16,zIndex:200,background:ds.green,borderRadius:14,padding:"14px 18px",display:"flex",alignItems:"center",gap:10,boxShadow:"0 8px 24px rgba(34,197,94,0.35)",animation:"sld .3s ease"}}><Check size={20} color="#fff"/><div><div style={{color:ds.txW,fontSize:14,fontWeight:700}}>Encounter Saved!</div><div style={{color:"rgba(255,255,255,0.7)",fontSize:12}}>Data recorded</div></div><style>{`@keyframes sld{from{transform:translateY(-20px);opacity:0}to{transform:translateY(0);opacity:1}}`}</style></div>}
export default function App(){const[scr,setScr]=useState("splash");const[tab,setTab]=useState("selectstu");const[sub,setSub]=useState(null);const[cfg,setCfg]=useState(null);const[stuInfo,setStuInfo]=useState(null);const[dur,setDur]=useState(0);const[toast,setToast]=useState(false);const[pearls,setPearls]=useState([...INIT_PEARLS]);const showTabs=["selectstu","history","stats","studhist","more"].includes(scr)&&!sub;const onStuNext=useCallback(info=>{setStuInfo(info);setScr("setup")},[]);const onStart=useCallback(c=>{setCfg(c);setScr("timer")},[]);const onDone=useCallback(d=>{setDur(d);setScr("log")},[]);const onSave=useCallback(()=>{setScr("selectstu");setTab("selectstu");setToast(true);setTimeout(()=>setToast(false),3000)},[]);const onTab=useCallback(tb=>{setTab(tb);setScr(tb);setSub(null)},[]);const onSavePearl=useCallback(p=>{setPearls(pr=>[...pr,{id:"p"+Date.now(),dept:p.dept,dx:p.dx,pts:p.pts,used:1,fav:false}])},[]);let content=null;if(sub==="pearls")content=<PearlLib pearls={pearls} onBack={()=>setSub(null)}/>;else if(sub==="about")content=<AboutScr onBack={()=>setSub(null)}/>;else if(sub==="settings")content=<AboutScr onBack={()=>setSub(null)}/>;else if(scr==="splash")content=<Splash onNext={()=>setScr("login")}/>;else if(scr==="login")content=<Login onLogin={()=>{setScr("selectstu");setTab("selectstu")}}/>;else if(scr==="selectstu")content=<StudentSelect onNext={onStuNext}/>;else if(scr==="setup")content=<SessionSetup studentInfo={stuInfo} onStart={onStart} onBack={()=>setScr("selectstu")}/>;else if(scr==="timer")content=<TimerScr config={cfg} onComplete={onDone} onCancel={()=>{setScr("selectstu");setTab("selectstu")}} pearls={pearls} onSavePearl={onSavePearl}/>;else if(scr==="log")content=<LogScr config={cfg} dur={dur} onSave={onSave}/>;else if(scr==="history")content=<HistoryScr/>;else if(scr==="stats")content=<StatsScr/>;else if(scr==="studhist")content=<StudentHistScr/>;else if(scr==="more")content=<MoreScr onNav={setSub} pc={pearls.length}/>;return <Phone><Toast show={toast}/>{content}<TabBar active={tab} onNav={onTab} show={showTabs}/></Phone>}
